selection_review=[
 {'pages':[3,4,16],'wording':'any four / any two / two questions','classification':'exam-level-selection','reason':'Retain every offered question and all 380 offered marks.'},
 {'pages':[4],'wording':'suitable chart','classification':'open-answer','reason':'Any valid labelled chart; one task, not multiple chart-type cards.'},
 {'pages':[7],'wording':'each of the four regions','classification':'required-answers','reason':'All four probabilities required on one Venn task.'},
 {'pages':[8],'wording':'for all values of k','classification':'universal-proof','reason':'A universal substitution statement, not a finite choice.'},
 {'pages':[11],'wording':'one possible equation of j and one possible equation of k','classification':'open-answer','reason':'One horizontal and one vertical tangent required together under one scale; alternative valid pairs are not expanded.'},
 {'pages':[13],'wording':'all the values of A','classification':'required-answers','reason':'All four angle solutions required.'},
 {'pages':[19,20,21],'wording':'groups of 5 / vowel / either small, medium, large, or extra large / at least 5','classification':'problem-data','reason':'Counting and probability data, not a student option pool.'},
 {'pages':[23,29],'wording':'using this value or your answer / part (ii) or part (iii)','classification':'alternative-method','reason':'Permitted solution routes share one task and tariff.'}
]
def classify(c):
 t=c['context'].lower()
 if 'questions' in t:return ('exam-level-selection','All offered questions retained.')
 if 'either small' in t:return ('problem-data','Egg size categories are data, not a choice.')
 if 'part (ii)' in t or 'part (iii)' in t:return ('alternative-method','Either preceding result can support the same proof.')
 if 'possible equation' in t:return ('open-answer','One horizontal and one vertical tangent under one allocation.')
 if 'one of the gridlines' in t:return ('problem-data','The given line is one grid member, not an option to choose.')
 if 'any one time' in t:return ('problem-data','Work group size is data for a counting problem.')
 return None
if __name__=='__main__':p.write(selection_review,classify)
